const BIOS={
 "Flt Lt T.F. Neil":{kills:14,sorties:"~140+",fate:"Survived",awards:["DFC Bar","AFC"],bio:`<p>Tom Neil flew Hurricanes with 249 Squadron and became one of the classic voices of the Battle of Britain. His accounts are especially useful to modellers because they describe scrambling, grass landings, quick servicing and the battered condition of hard-used Hurricanes.</p>`},
 "Flt Lt W. Urbanowicz":{kills:17,sorties:"~90+",fate:"Survived",awards:["Virtuti Militari","DFC"],bio:`<p>Witold Urbanowicz led 303 Polish Squadron during its peak Battle of Britain period. RF-coded Hurricanes, Polish checkerboards and Northolt operations make this one of the strongest Hurricane modelling subjects.</p>`},
 "Sgt J. František":{kills:17,sorties:"~80+",fate:"KIA Oct 1940",awards:["DFM","Virtuti Militari"],bio:`<p>Josef František, a Czech pilot with 303 Squadron, became one of the highest-scoring pilots of the battle. His Hurricane story is closely tied to RF-coded 303 Squadron subjects.</p>`},
 "Sqn Ldr D.R.S. Bader":{kills:22,sorties:"~170+",fate:"POW 1941",awards:["DSO","DFC"],bio:`<p>Douglas Bader commanded 242 Squadron, a Canadian-manned Hurricane unit, and became associated with the 12 Group Big Wing debate. His 1940 Hurricane period is often overlooked by modellers.</p>`},
 "Flt Lt I.R. Gleed":{kills:13,sorties:"~120+",fate:"KIA 1943",awards:["DSO","DFC"],bio:`<p>Ian 'Widge' Gleed flew Hurricanes with 87 Squadron from Exeter. His aircraft connect the Hurricane to 10 Group defence and West Country operating conditions.</p>`},
 "Sqn Ldr P.W. Townsend":{kills:9,sorties:"~130+",fate:"Survived",awards:["DFC Bar"],bio:`<p>Peter Townsend commanded 85 Squadron after the Battle of France. His Hurricane story is one of rebuilding, absorbing losses and continuing the defence in battered but serviceable aircraft.</p>`}
};

