// ═══ STATE ═══
let activeFilter='all',activeSort='num',activeId=null,activeTab='squadrons';

// ═══ FILTER/SORT/GRID ═══
function setFilter(g,el){activeFilter=g;document.querySelectorAll('.fb.gf').forEach(b=>b.classList.remove('on'));el.classList.add('on');closeDetail();renderGrid();}
function setSort(s,el){activeSort=s;document.querySelectorAll('.fb.sf').forEach(b=>b.classList.remove('on'));el.classList.add('on');renderGrid();}
function renderGrid(){
  const grid=document.getElementById('grid');
  let list=activeFilter==='all'?[...SQ]:SQ.filter(s=>s.group===activeFilter);
  if(activeSort==='kills')list.sort((a,b)=>b.kills-a.kills);
  else if(activeSort==='killrate')list.sort((a,b)=>(b.kills/b.sorties)-(a.kills/a.sorties));
  else if(activeSort==='base')list.sort((a,b)=>a.base.localeCompare(b.base));
  else list.sort((a,b)=>parseInt(a.num)-parseInt(b.num));
  document.getElementById('sq-count').textContent=`${list.length} squadron${list.length!==1?'s':''}`;
  grid.innerHTML=list.map(sq=>`
    <div class="sq-card" id="card-${sq.num}" onclick="selectSq('${sq.num}')">
      <div class="card-hd"><div class="card-circle">${sq.num}</div>
        <div><div class="card-name">No.${sq.num} Sqn — ${sq.codes}</div>
        <div class="card-base">${sq.base} &nbsp;·&nbsp; ${sq.group} Group</div></div>
      </div>
      <div class="card-body">
        <div class="card-stats">
          <div class="stat"><div class="stat-val">${sq.kills}</div><div class="stat-lbl">Claims</div></div>
          <div class="stat"><div class="stat-val">${sq.sorties}</div><div class="stat-lbl">Sorties</div></div>
          <div class="stat"><div class="stat-val">${(sq.kills/sq.sorties*100).toFixed(1)}%</div><div class="stat-lbl">Kill %</div></div>
        </div>
        <div class="card-tags">${sq.tags.map((t,i)=>`<span class="tag ${t}">${sq.tagTxt[i]}</span>`).join('')}</div>
        <div style="margin-top:.5rem;font-family:'Oswald',sans-serif;font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:var(--ink3)">Click to expand — pilots · photos · decals · kits</div>
      </div>
    </div>
  `).join('')+'<div id="detail-panel" class="detail-panel"></div>';
}

// ═══ TABS ═══
function switchTab(id,el){
  document.querySelectorAll('.tab-panel').forEach(p=>p.classList.remove('active'));
  document.querySelectorAll('.nav-tab').forEach(t=>t.classList.remove('active'));
  document.getElementById('tab-'+id).classList.add('active');
  el.classList.add('active');
  document.getElementById('sqn-bar').style.display=id==='squadrons'?'flex':'none';
  activeTab=id;
  if(id==='build'){if(!document.querySelector('.kit-card'))renderKits();if(!document.querySelector('.paint-card'))renderPaint();if(!document.querySelector('.am-card'))renderAftermarket();if(!document.querySelector('.weather-card'))renderWeathering();renderStepByStep();renderColourCompare();}
  if(id==='reference'){if(!document.querySelector('.survivor-card'))renderSurvivors();if(!document.querySelector('.book-card'))renderBooks();renderMap();}
  if(id==='stories'){renderPilotStories();renderThisWeek();}
  if(id==='media'){renderMedia();}
}
function setBuildSub(sub,el){document.querySelectorAll('.btf').forEach(b=>b.classList.remove('on'));el.classList.add('on');['kits','aftermarket','paint','stepbystep','weathering'].forEach(s=>{const e2=document.getElementById('bsub-'+s);if(e2)e2.style.display=s===sub?'':''[s=sub?0:1];});}
function setBuildSub(sub,el){document.querySelectorAll('.btf').forEach(b=>b.classList.remove('on'));el.classList.add('on');['kits','aftermarket','paint','stepbystep','weathering'].forEach(s=>{const e2=document.getElementById('bsub-'+s);if(e2)e2.style.display=s===sub?'':'none';});}
function setRefSub(sub,el){document.querySelectorAll('.rtf').forEach(b=>b.classList.remove('on'));el.classList.add('on');['map','timeline','compare','survivors','books'].forEach(s=>{const e2=document.getElementById('rsub-'+s);if(e2)e2.style.display=s===sub?'':'none';});if(sub==='timeline'){updateTimeline(document.getElementById('tl-slider').value||0);}if(sub==='map'){renderMap();}if(sub==='compare'){initCompare();}}

// ═══ SQUAD DETAIL ═══
function selectSq(num){if(activeId===num){closeDetail();return;}activeId=num;document.querySelectorAll('.sq-card').forEach(c=>c.classList.remove('active'));const card=document.getElementById('card-'+num);if(card)card.classList.add('active');showDetail(num);setTimeout(()=>{const p=document.getElementById('detail-panel');if(p)p.scrollIntoView({behavior:'smooth',block:'nearest'});},50);}
function closeDetail(){activeId=null;document.querySelectorAll('.sq-card').forEach(c=>c.classList.remove('active'));const p=document.getElementById('detail-panel');if(p){p.classList.remove('open');p.innerHTML='';}}

function showDetail(num){
  const sq=SQ.find(s=>s.num===num);
  const panel=document.getElementById('detail-panel');
  const sqDecals=SQ_DECALS[num]||[];
  panel.innerHTML=`
    <div class="dp-top">
      <div><div class="dp-title">No. ${sq.num} Squadron RAF — ${sq.codes}</div>
      <div class="dp-meta">Base: ${sq.base} &nbsp;·&nbsp; ${sq.group} Group &nbsp;·&nbsp; ${sq.pilots.length} pilots &nbsp;·&nbsp; ${sq.kills} claims / ${sq.sorties} sorties &nbsp;·&nbsp; ${(sq.kills/sq.sorties*100).toFixed(1)}% kill rate</div></div>
      <button class="close-btn" onclick="closeDetail()">Close ✕</button>
    </div>
    <div style="padding:1rem 1.2rem 1.4rem">
      <div class="sec-label">Operations</div>
      <div class="ops-text" style="margin-bottom:1.2rem">${sq.ops}</div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:1.2rem;margin-bottom:1.2rem">
        <div>
          <div class="sec-label">All Pilots</div>
          <div class="pilot-grid" style="grid-template-columns:1fr">
            ${sq.pilots.map(p=>`
              <div class="pilot-card" onclick="openPM('${p.n.replace(/'/g,"\\'")}')">
                <span class="pkills">${p.k}</span>
                <div class="pname">${p.n}</div>
                <div class="pnote">${p.note}</div>
                ${p.awards&&p.awards!=='—'?`<div style="font-size:13px;color:var(--gold2);margin-top:2px">${p.awards}</div>`:''}
                <div style="font-family:'Oswald',sans-serif;font-size:12px;letter-spacing:.05em;color:var(--ink3);margin-top:2px">${p.fate}</div>
              </div>`).join('')}
          </div>
        </div>
        <div>
          <div class="sec-label">Photographs</div>
          <div class="photo-grid" id="photos-${sq.num}"><div class="photo-loading">Loading…</div></div>
          <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:.5rem">
            <a href="https://www.iwm.org.uk/collections" target="_blank" rel="noopener" style="font-family:'Oswald',sans-serif;font-size:12px;letter-spacing:.07em;text-transform:uppercase;color:var(--brass);text-decoration:none;padding:3px 8px;border:1px solid rgba(184,144,42,.3);border-radius:2px">IWM Archive ↗</a>
            <a href="https://commons.wikimedia.org/w/index.php?search=No+${sq.num}+Squadron+RAF+Hurricane&ns6=1" target="_blank" rel="noopener" style="font-family:'Oswald',sans-serif;font-size:12px;letter-spacing:.07em;text-transform:uppercase;color:var(--raf-sky);text-decoration:none;padding:3px 8px;border:1px solid rgba(74,127,165,.3);border-radius:2px">Wikimedia ↗</a>
          </div>
        </div>
      </div>
      <div class="sec-label">Marking Reference — ${sq.decalRef.codes} (${sq.decalRef.serial})</div>
      <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:6px;margin-bottom:1.2rem">
        ${Object.entries({'Code letters':sq.decalRef.codes,'Serial':sq.decalRef.serial,'Code colour':sq.decalRef.codeColour,'Upper roundel':sq.decalRef.roundelUpper,'Fuselage roundel':sq.decalRef.roundelFuselage,'Lower roundel':sq.decalRef.roundelLower,'Spinner':sq.decalRef.spinner,'Fin flash':sq.decalRef.finFlash,...(sq.decalRef.special?{'Special note':sq.decalRef.special}:{})}).map(([k,v])=>`
          <div style="background:rgba(0,0,0,.25);border:1px solid rgba(255,255,255,.1);border-radius:2px;padding:5px 8px">
            <div style="font-family:'Oswald',sans-serif;font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:rgba(255,255,255,.4)">${k}</div>
            <div style="font-size:13px;color:rgba(255,255,255,.85);margin-top:1px">${v}</div>
          </div>`).join('')}
      </div>
      <div class="sec-label">Specific Decal Sheets</div>
      ${sqDecals.length?`<div style="display:flex;flex-direction:column;gap:5px;margin-bottom:1rem">${sqDecals.filter(d=>d.url).map(d=>`<a href="${d.url}" target="_blank" style="display:flex;align-items:center;gap:8px;background:rgba(0,0,0,.2);border:1px solid rgba(255,255,255,.1);border-left:3px solid var(--brass);border-radius:2px;padding:6px 10px;text-decoration:none" onmouseover="this.style.background='rgba(255,255,255,.05)'" onmouseout="this.style.background='rgba(0,0,0,.2)'" rel="noopener"><span style="font-size:12px">↗</span><span style="font-size:13px;color:rgba(255,255,255,.8)">${d.name}</span></a>`).join('')}</div>`:`<div style="font-size:13px;color:rgba(255,255,255,.4);margin-bottom:1rem">Search Hannants or Barracuda for this squadron.</div>`}
      <div style="display:flex;gap:6px;flex-wrap:wrap">
        <a href="https://www.hannants.co.uk/search/?keyword_search=${sq.num}+squadron+hurricane" target="_blank" rel="noopener" class="shop-btn hb-brass" style="font-size:13px">Hannants: all ${sq.num} Sqn decals ↗</a>
        <a href="https://barracudacals.com/collections/hurricane" target="_blank" rel="noopener" class="shop-btn hb-outline" style="font-size:13px">Barracuda Hurricane decals ↗</a>
      </div>
    </div>`;
  panel.classList.add('open');
  let photosLoaded=0;
  const photoGrid=document.getElementById('photos-'+num);
  // After 3s, if still Loading show fallback
  setTimeout(()=>{
    const g=document.getElementById('photos-'+num);
    if(g&&g.querySelector('.photo-loading')){
      g.innerHTML='<div style="grid-column:1/-1;font-size:13px;color:rgba(255,255,255,.35);line-height:1.6;padding:.5rem 0">No photos loaded.<br>Try the IWM and Wikimedia links above.</div>';
    }
  },4000);
  sq.pilots.forEach(p=>{
    const wikiName=p.wiki||(p.n.replace(/^(Sqn Ldr|Flt Lt|Plt Off|Sub Lt|Sgt|Flg Off)\s+/,'').replace(/\s+/g,'_'));
    fetch('https://en.wikipedia.org/api/rest_v1/page/summary/'+encodeURIComponent(wikiName))
      .then(r=>r.json()).then(d=>{
        const img=d.thumbnail&&d.thumbnail.source;if(!img)return;
        const grid=document.getElementById('photos-'+num);if(!grid)return;
        if(grid.querySelector('.photo-loading'))grid.innerHTML='';
        const div=document.createElement('div');
        div.style.cssText='overflow:hidden;border-radius:2px;border:1px solid rgba(255,255,255,.1);cursor:pointer;';
        div.innerHTML=`<img src="${img}" alt="${p.n}" style="width:100%;height:90px;object-fit:cover;object-position:top center" onclick="openLB('${img}','${p.n}')">`;
        grid.appendChild(div);
        photosLoaded++;
      }).catch(()=>{});
  });
}

// ═══ PILOT MODAL ═══
function openPM(name){
  const bio=BIOS[name];if(!bio)return;
  document.getElementById('pm-name').textContent=name;
  document.getElementById('pm-rank').textContent=`${bio.kills} victories · ${bio.fate}`;
  document.getElementById('pm-kills').textContent=bio.kills;
  document.getElementById('pm-sorties').textContent=bio.sorties||'—';
  document.getElementById('pm-fate-short').textContent=bio.fate.split(' — ')[0].split(',')[0];
  document.getElementById('pm-bio').innerHTML=bio.bio;
  document.getElementById('pm-awards').innerHTML=(bio.awards||[]).map(a=>`<span class="award">${a}</span>`).join('');
  const surname=name.split(' ').slice(-1)[0];
  const pl=document.getElementById('pm-h-pilot');
  pl.href=`https://www.iwm.org.uk/collections`;
  pl.textContent=`IWM: ${surname} archive ↗`;
  const sqnFP=SQ.find(s=>s.pilots.some(p=>p.n===name));
  const sl=document.getElementById('pm-h-sqn');
  if(sqnFP){sl.href=`https://www.hannants.co.uk/search/?keyword_search=${sqnFP.num}+squadron+hurricane`;sl.textContent=`Hannants: No.${sqnFP.num} Sqn decals ↗`;sl.style.display='';}else{sl.style.display='none';}
  document.getElementById('pm-overlay').classList.add('open');
}
function closePM(){document.getElementById('pm-overlay').classList.remove('open');}
function openLB(src,cap){document.getElementById('lb-img').src=src;document.getElementById('lb-cap').textContent=cap;document.getElementById('lightbox').classList.add('open');}
function closeLB(){document.getElementById('lightbox').classList.remove('open');}

