// ═══ PILOT STORIES ═══
function renderPilotStories(){
  const el=document.getElementById('pilot-stories-grid');if(!el||el.dataset.rendered)return;el.dataset.rendered='1';
  el.innerHTML=PILOT_STORIES.map((p,i)=>`
    <div style="background:rgba(21,39,68,.7);border:1px solid rgba(255,255,255,.1);border-top:3px solid var(--brass);border-radius:3px;padding:1.4rem;margin-bottom:1.5rem">
      <div style="display:flex;gap:1.2rem;align-items:flex-start;margin-bottom:1rem;flex-wrap:wrap">
        <div id="story-photo-${i}" style="width:80px;height:100px;flex-shrink:0;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.12);border-radius:2px;display:flex;align-items:center;justify-content:center;overflow:hidden"><div style="font-size:2rem;opacity:.2">✈</div></div>
        <div style="flex:1;min-width:200px">
          <div style="font-family:'Special Elite',cursive;font-size:1.4rem;color:#fff;margin-bottom:.3rem">${p.name}</div>
          <div style="font-family:'Oswald',sans-serif;font-size:11px;letter-spacing:.12em;text-transform:uppercase;color:var(--brass);margin-bottom:.5rem">No.${p.sqn} Squadron &nbsp;·&nbsp; ${p.kills} victories</div>
          <div style="display:flex;gap:.5rem;flex-wrap:wrap">
            ${p.callsign!=='—'?`<span style="font-family:'Oswald',sans-serif;font-size:11px;letter-spacing:.08em;text-transform:uppercase;background:rgba(184,144,42,.15);color:var(--brass2);padding:2px 8px;border:1px solid rgba(184,144,42,.3);border-radius:2px">"${p.callsign}"</span>`:''}
            <span style="font-family:'Oswald',sans-serif;font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:rgba(255,255,255,.35);padding:2px 8px;border:1px solid rgba(255,255,255,.1);border-radius:2px">${p.aircraft||'Hurricane Mk.I'}</span>
          </div>
        </div>
      </div>
      <div style="font-size:16px;color:rgba(255,255,255,.82);line-height:1.85;font-family:'Source Serif 4',Georgia,serif;border-top:1px solid rgba(255,255,255,.07);padding-top:1rem">${p.story}</div>
    </div>`).join('');
  PILOT_STORIES.forEach(function(p,i){
    if(!p.wiki)return;
    fetch('https://en.wikipedia.org/api/rest_v1/page/summary/'+encodeURIComponent(p.wiki)).then(function(r){return r.json();}).then(function(d){const img=d.thumbnail&&d.thumbnail.source;if(!img)return;const box=document.getElementById('story-photo-'+i);if(box)box.innerHTML='<img src="'+img+'" alt="'+p.name+'" style="width:100%;height:100%;object-fit:cover;object-position:top center">';}).catch(function(){});
  });
}

// ═══ THIS WEEK IN BoB ═══
function renderThisWeek(){
  const el=document.getElementById('this-week-bob');if(!el||el.dataset.rendered)return;el.dataset.rendered='1';
  const now=new Date();const m=now.getMonth()+1,d=now.getDate();
  const md=(m<10?'0':'')+m+'-'+(d<10?'0':'')+d;
  const best=BOB_EVENTS.find(e=>e.md===md)||BOB_EVENTS[Math.floor(Math.random()*BOB_EVENTS.length)];
  const [bm,bd]=best.md.split('-');const date1940=new Date(1940,parseInt(bm)-1,parseInt(bd));
  el.innerHTML=`<div style="background:rgba(21,39,68,.8);border:2px solid var(--brass);border-radius:4px;overflow:hidden"><div style="background:rgba(0,0,0,.35);padding:.75rem 1.2rem;display:flex;align-items:center;gap:1rem;border-bottom:1px solid rgba(184,144,42,.3)"><div style="text-align:center;background:var(--brass);color:var(--raf-dark);padding:.4rem .6rem;border-radius:2px;flex-shrink:0"><div style="font-family:'Special Elite',cursive;font-size:1.8rem;line-height:1">${bd}</div><div style="font-family:'Oswald',sans-serif;font-size:12px;font-weight:600;letter-spacing:.08em;text-transform:uppercase">${date1940.toLocaleString('en-GB',{month:'short'})} 1940</div></div><div><div style="font-family:'Oswald',sans-serif;font-size:13px;letter-spacing:.15em;text-transform:uppercase;color:var(--brass);margin-bottom:.3rem">${(now.getMonth()*100 + now.getDate() >= 620 && now.getMonth()*100 + now.getDate() <= 1103) ? 'This week in the BoB' : 'On this date in the BoB'}</div><div style="font-family:'Special Elite',cursive;font-size:1.2rem;color:#fff">${yearsAgo} years ago</div></div></div><div style="padding:1rem 1.2rem;font-size:17px;color:rgba(255,255,255,.85);line-height:1.75">${best.text}</div></div>`;
}

// ═══ MEDIA ═══
function renderMedia(){
  const el=document.getElementById('media-grid');if(!el||el.dataset.rendered)return;el.dataset.rendered='1';
  const cats=[{k:'video',label:'Video',col:'var(--raf-sky)'},{k:'audio',label:'Audio',col:'var(--brass)'},{k:'archive',label:'Archive',col:'var(--olive)'}];
  cats.forEach(cat=>{
    const items=MEDIA_ITEMS.filter(i=>i.type===cat.k);if(!items.length)return;
    const sec=document.createElement('div');
    sec.innerHTML=`<div class="section-label" style="color:${cat.col}">${cat.label}</div>`;
    items.forEach(item=>{
      const div=document.createElement('a');div.href=item.url;div.target='_blank';div.rel='noopener';
      div.style.cssText='display:flex;gap:.9rem;background:rgba(21,39,68,.7);border:1px solid rgba(255,255,255,.1);border-radius:3px;padding:.9rem 1rem;margin-bottom:8px;text-decoration:none;transition:background .15s;align-items:flex-start';
      div.onmouseover=()=>div.style.background='rgba(255,255,255,.04)';div.onmouseout=()=>div.style.background='rgba(21,39,68,.7)';
      div.innerHTML=`<div style="font-size:1.8rem;flex-shrink:0;line-height:1;padding-top:.1rem">${item.thumb}</div><div><div style="font-family:'Special Elite',cursive;font-size:1.05rem;color:#fff;margin-bottom:.25rem">${item.title}</div><div style="font-size:15px;color:rgba(255,255,255,.6);line-height:1.55">${item.desc}</div><div style="font-family:'Oswald',sans-serif;font-size:12px;letter-spacing:.07em;text-transform:uppercase;color:${cat.col};margin-top:.4rem">Open ↗</div></div>`;
      sec.appendChild(div);
    });
    el.appendChild(sec);
  });
}

