(function(){
  if(window.__ww2MobileAircraftNavFix) return;
  window.__ww2MobileAircraftNavFix = true;

  function closeAll(except){
    document.querySelectorAll('.ac-drop.open').forEach(function(drop){
      if(drop !== except){
        drop.classList.remove('open');
        var b = drop.querySelector('.ac-drop-btn');
        if(b) b.setAttribute('aria-expanded','false');
      }
    });
  }

  document.addEventListener('click', function(e){
    var btn = e.target.closest && e.target.closest('.ac-drop-btn');
    if(btn){
      var drop = btn.closest('.ac-drop');
      if(drop){
        e.preventDefault();
        e.stopPropagation();
        var willOpen = !drop.classList.contains('open');
        closeAll(drop);
        drop.classList.toggle('open', willOpen);
        btn.setAttribute('aria-expanded', willOpen ? 'true' : 'false');
        return;
      }
    }
    var openDrop = e.target.closest && e.target.closest('.ac-drop.open');
    if(!openDrop) closeAll();
  }, true);

  document.addEventListener('keydown', function(e){
    if(e.key === 'Escape') closeAll();
  });
})();


