/* FINAL TOP NAV DROPDOWN FIX: click/tap safe, no dependency on old duplicated scripts. */
(function(){
  if(window.__ww2FinalNavDropdownFix) return;
  window.__ww2FinalNavDropdownFix = true;
  function closeAll(except){
    document.querySelectorAll('.ac-drop.open').forEach(function(drop){
      if(drop !== except){
        drop.classList.remove('open');
        var btn = drop.querySelector('.ac-drop-btn');
        if(btn) btn.setAttribute('aria-expanded','false');
      }
    });
  }
  function toggle(drop, force){
    if(!drop) return;
    var open = force == null ? !drop.classList.contains('open') : !!force;
    closeAll(open ? drop : null);
    drop.classList.toggle('open', open);
    var btn = drop.querySelector('.ac-drop-btn');
    if(btn) btn.setAttribute('aria-expanded', open ? 'true' : 'false');
  }
  document.addEventListener('pointerdown', function(e){
    var btn = e.target.closest && e.target.closest('.ac-drop-btn');
    if(btn){
      var drop = btn.closest('.ac-drop');
      if(drop){ e.preventDefault(); e.stopPropagation(); toggle(drop); }
      return;
    }
    if(!(e.target.closest && e.target.closest('.ac-drop-menu'))) closeAll();
  }, true);
  document.addEventListener('click', function(e){
    var btn = e.target.closest && e.target.closest('.ac-drop-btn');
    if(btn){ e.preventDefault(); e.stopPropagation(); return false; }
  }, true);
  document.addEventListener('keydown', function(e){ if(e.key === 'Escape') closeAll(); });
})();


